//! Shared game preparation writes generated bytes to a native cache or worker memory.
use crate::source::ReadAssets;
use anyhow::{Context, Result};
use std::{collections::BTreeMap, path::Path};

/// Generated paths are relative to the cache, never to the original installation.
pub(crate) trait Output {
    fn read(&self, path: &Path) -> Option<Vec<u8>>;
    fn exists(&self, path: &Path) -> bool;
    fn remove(&mut self, path: &Path) -> Result<()>;
    fn publish(&mut self, path: &Path, bytes: &[u8]) -> Result<()>;
    fn image(&mut self, path: &Path, image: &image::RgbaImage) -> Result<()> {
        let mut bytes = std::io::Cursor::new(Vec::new());
        image.write_to(&mut bytes, image::ImageFormat::Png)?;
        self.publish(path, &bytes.into_inner())
    }
}

impl Output for BTreeMap<String, Vec<u8>> {
    fn read(&self, path: &Path) -> Option<Vec<u8>> {
        self.get(path.to_str()?).cloned()
    }
    fn exists(&self, path: &Path) -> bool {
        path.to_str().is_some_and(|path| self.contains_key(path))
    }
    fn remove(&mut self, path: &Path) -> Result<()> {
        self.remove(path.to_str().context("generated path is not UTF-8")?);
        Ok(())
    }
    fn publish(&mut self, path: &Path, bytes: &[u8]) -> Result<()> {
        let path = path.to_str().context("generated path is not UTF-8")?;
        crate::validate_path(path)?;
        self.insert(path.to_owned(), bytes.to_vec());
        Ok(())
    }
}

/// Resolve authored DOS paths against the validated, case-insensitive source manifest.
pub(crate) fn path(source: &dyn ReadAssets, name: &str) -> Result<String> {
    let name = name.replace('\\', "/");
    crate::validate_path(&name)?;
    source
        .manifest()
        .find(&name)
        .map(|file| file.path.clone())
        .with_context(|| format!("missing original file {name}"))
}

pub(crate) fn read(source: &dyn ReadAssets, name: &str) -> Result<Vec<u8>> {
    source.read(&path(source, name)?)
}

pub(crate) fn text(source: &dyn ReadAssets, name: &str) -> Result<String> {
    source.text(&path(source, name)?)
}

pub(crate) fn soup(source: &dyn ReadAssets) -> Result<rgpre::import::soup_def::SoupDef> {
    rgpre::import::soup_def::parse_soup_def(&text(source, "soup386/SOUP386.DEF")?)
        .map_err(anyhow::Error::msg)
        .context("soup386/SOUP386.DEF")
}

#[cfg(all(feature = "native", not(target_arch = "wasm32")))]
pub(crate) struct DiskOutput<'a>(pub &'a Path);
#[cfg(all(feature = "native", not(target_arch = "wasm32")))]
impl Output for DiskOutput<'_> {
    fn read(&self, path: &Path) -> Option<Vec<u8>> {
        std::fs::read(self.0.join(path)).ok()
    }
    fn exists(&self, path: &Path) -> bool {
        self.0.join(path).is_file()
    }
    fn remove(&mut self, path: &Path) -> Result<()> {
        if self.exists(path) {
            std::fs::remove_file(self.0.join(path))?;
        }
        Ok(())
    }
    fn publish(&mut self, path: &Path, bytes: &[u8]) -> Result<()> {
        crate::validate_path(path.to_str().context("generated path is not UTF-8")?)?;
        crate::native::publish(&self.0.join(path), bytes)
    }
}
